perl -0777 -e '
use strict; use warnings;
sub rc { my $s=reverse shift; $s =~ tr/ACGT/TGCA/; return $s }
sub fasta { my ($path)=@_; open my $fh,"<",$path or die "$path: $!"; local $/; my $x=<$fh>; my %r; for (split /^>/m,$x) { next unless /\S/; my ($h,@l)=split /\n/; my $s=join "",@l; $s=~s/\s+//g; $r{$h}=uc$s } return %r }
my %s=fasta("sequences.fasta"); my %p=fasta("primers.fasta");
my ($in,$out)=@s{qw(input output)}; my ($f,$r)=@p{qw(pair1_forward pair1_reverse)};
my $pos=0; $pos++ while substr($in,$pos,1) eq substr($out,$pos,1); my $suf=0; $suf++ while substr($in,length($in)-1-$suf,1) eq substr($out,length($out)-1-$suf,1); my $ins=substr($out,$pos,length($out)-length($in));
my $fo=substr($f,0,20); my $fa=substr($f,20); my $ro=substr($r,0,19); my $ra=substr($r,19);
my $expected_fa=substr($in,$pos,19); my $expected_ra=rc(substr($in,$pos-36,36));
my $assembled=rc($r).$f; my $target_segment=substr($out,$pos-36,36+39+19);
sub tm { my ($x)=@_; my $v=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $x`; chomp $v; return $v }
printf "edit: insertion at input position %d, length %d\n",$pos+1,length($ins);
printf "forward: total %d, annealing %d, Tm %.6f\n",length($f),length($fa),tm($fa);
printf "reverse: total %d, annealing %d, Tm %.6f\n",length($r),length($ra),tm($ra);
printf "Tm difference: %.6f\n",abs(tm($fa)-tm($ra));
print "annealing matches input: ",($fa eq $expected_fa && $ra eq $expected_ra ? "yes\n":"no\n");
print "reconstructed local output segment: ",($assembled eq $target_segment ? "yes\n":"no\n");
print "single pair is minimum: ",($pos>=0 && length($ins)>0 ? "yes (one insertion event)\n":"no\n");
'
